"""Read-only signatures and invariants; no content, credentials or tokens exported."""
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess

from psycopg2 import sql

run=Path(os.environ['YDENTAL_S08B_RUN_DIR']);assert run.name==env.cr.dbname and re.fullmatch(r'ydental_s08b_test_[0-9]{14}_[a-f0-9]{8}',env.cr.dbname)
result={'database':env.cr.dbname,'tested_commit':subprocess.check_output(['git','-C',str(Path(__file__).resolve().parents[1]),'rev-parse','HEAD'],text=True).strip(),'signatures':{},'invariants':{}}
env.cr.execute('SELECT name,setting FROM pg_settings WHERE name=ANY(%s)', [
    ['max_parallel_workers_per_gather','max_parallel_maintenance_workers','maintenance_work_mem']])
result['session_settings']=dict(env.cr.fetchall())
assert result['session_settings']=={'max_parallel_workers_per_gather':'0','max_parallel_maintenance_workers':'0','maintenance_work_mem':'16384'}

# Fixed server identifiers, never supplied by a client.
for table in ('ydental_clinical_document','ydental_clinical_version','ydental_queue_execution','ydental_intake_task','ydental_inventory_event','ydental_inventory_batch','stock_move','stock_move_line','stock_quant','ydental_intake_snapshot','ydental_treatment_event','ydental_treatment_fee','ydental_treatment_order','ydental_treatment_line','ydental_treatment_segment','ydental_treatment_consumption','ydental_treatment_price_review','ydental_queue_entry','ydental_queue_lease','ydental_supply_claim'):
    env.cr.execute(sql.SQL('SELECT row_to_json(t)::text FROM {} t ORDER BY id').format(sql.Identifier(table)))
    rows=env.cr.fetchall();result['signatures'][table]={'count':len(rows),'sha256':hashlib.sha256('\n'.join(r[0] for r in rows).encode()).hexdigest()}
queries={
 'version_count':'''SELECT count(*) FROM ydental_clinical_document d WHERE d.ydental_version<>(SELECT count(*) FROM ydental_clinical_version v WHERE v.ydental_document_id=d.id)''',
 'latest_content':'''SELECT count(*) FROM ydental_clinical_document d JOIN ydental_clinical_version v ON v.ydental_document_id=d.id AND v.ydental_number=d.ydental_version WHERE d.ydental_content<>v.ydental_content''',
 'version_source':'''SELECT count(*) FROM ydental_clinical_version v JOIN ydental_clinical_document d ON v.ydental_document_id=d.id WHERE v.ydental_store_id<>d.ydental_store_id OR v.ydental_patient_id<>d.ydental_patient_id''',
 'document_source':'''SELECT count(*) FROM ydental_clinical_document d JOIN ydental_queue_execution e ON d.ydental_execution_id=e.id WHERE d.ydental_store_id<>e.ydental_store_id OR d.ydental_patient_id<>e.ydental_patient_id''',
 'duplicate_continuation':'''SELECT count(*) FROM (SELECT ydental_source_execution_id FROM ydental_intake_task WHERE ydental_source_execution_id IS NOT NULL GROUP BY ydental_source_execution_id HAVING count(*)>1) q''',
 'duplicate_actual_execution':'''SELECT count(*) FROM (SELECT ydental_patient_id FROM ydental_queue_execution WHERE state IN ('serving','verify') GROUP BY ydental_patient_id HAVING count(*)>1) q''',
 'terminal_unmarked_draft':'''SELECT count(*) FROM ydental_clinical_document d JOIN ydental_queue_execution e ON d.ydental_current_execution_id=e.id WHERE e.state IN ('handover','interrupted') AND d.state='draft' ''',
 'negative_internal_quant':'''SELECT count(*) FROM stock_quant q JOIN stock_location l ON l.id=q.location_id WHERE l.usage='internal' AND q.quantity<0''',
}
queries.update({'recovery_evidence_mismatch': "SELECT count(*) FROM ydental_inventory_event e LEFT JOIN ydental_inventory_event c ON c.id=e.ydental_correction_id WHERE e.ydental_reconciled_at IS NOT NULL AND (e.state!='done' OR c.state!='done' OR c.ydental_lot_id!=e.ydental_lot_id OR c.ydental_store_id!=e.ydental_store_id OR c.ydental_to_id!=e.ydental_from_id OR c.ydental_kind NOT IN ('receipt','inventory') OR e.ydental_reconciled_at<e.ydental_actual_at OR c.id IS NULL)", 'negative_internal_quant': "SELECT count(*) FROM stock_quant q JOIN stock_location l ON l.id=q.location_id WHERE l.ydental_store_id IS NOT NULL AND l.usage='internal' AND q.quantity < -0.000001", 'duplicate_source': 'SELECT count(*) FROM (SELECT ydental_store_id,ydental_source_namespace,ydental_source_key FROM ydental_inventory_event GROUP BY 1,2,3 HAVING count(*)>1) d', 'half_event': "SELECT count(*) FROM ydental_inventory_event e LEFT JOIN stock_move m ON m.id=e.ydental_move_id WHERE (e.state='done' AND (m.id IS NULL OR m.state!='done')) OR (e.state='pending' AND (m.id IS NOT NULL OR e.ydental_responsible_id IS NULL))", 'event_move_quantity_mismatch': 'SELECT count(*) FROM ydental_inventory_event e JOIN stock_move m ON m.id=e.ydental_move_id WHERE abs(e.ydental_quantity-m.quantity)>0.000001 OR e.ydental_product_id!=m.product_id OR e.ydental_from_id!=m.location_id OR e.ydental_to_id!=m.location_dest_id', 'movement_audit_mismatch': "SELECT count(*) FROM ydental_inventory_event e WHERE e.state='done' AND (SELECT count(*) FROM ydental_access_audit a WHERE a.ydental_event='inventory.movement' AND a.ydental_target_model='ydental.inventory.event' AND a.ydental_target_id=e.id)!=1", 'quant_move_reconciliation': "WITH deltas AS (\nSELECT ml.product_id,ml.lot_id,ml.location_dest_id loc,ml.quantity qty FROM stock_move_line ml JOIN stock_move m ON m.id=ml.move_id WHERE m.state='done'\nUNION ALL SELECT ml.product_id,ml.lot_id,ml.location_id loc,-ml.quantity qty FROM stock_move_line ml JOIN stock_move m ON m.id=ml.move_id WHERE m.state='done'),\nm AS (SELECT product_id,lot_id,loc,sum(qty) qty FROM deltas GROUP BY 1,2,3),\nq AS (SELECT product_id,lot_id,location_id loc,sum(quantity) qty FROM stock_quant GROUP BY 1,2,3)\nSELECT count(*) FROM m FULL OUTER JOIN q USING(product_id,lot_id,loc) JOIN stock_location l ON l.id=coalesce(m.loc,q.loc)\nWHERE l.ydental_store_id IS NOT NULL AND abs(coalesce(m.qty,0)-coalesce(q.qty,0))>0.000001", 'wrong_quant_store': 'SELECT count(*) FROM stock_quant q JOIN stock_location l ON l.id=q.location_id WHERE l.ydental_store_id IS NOT NULL AND q.ydental_store_id IS DISTINCT FROM l.ydental_store_id', 'confirmed_fee_unique': "SELECT count(*) FROM ydental_treatment_event e WHERE (e.state='confirmed' AND (SELECT count(*) FROM ydental_treatment_fee f WHERE f.ydental_event_id=e.id)<>1) OR (e.state='pending' AND EXISTS(SELECT 1 FROM ydental_treatment_fee f WHERE f.ydental_event_id=e.id))", 'confirmed_stock_complete': "SELECT count(*) FROM ydental_treatment_consumption c JOIN ydental_treatment_event e ON c.ydental_event_id=e.id LEFT JOIN ydental_inventory_event i ON c.ydental_inventory_event_id=i.id WHERE e.state='confirmed' AND (i.id IS NULL OR i.state<>'done')", 'source_identity': 'SELECT count(*) FROM ydental_treatment_event e JOIN ydental_queue_execution x ON x.id=e.ydental_execution_id JOIN ydental_queue_lease lx ON lx.id=x.ydental_lease_id WHERE (e.ydental_store_id,e.ydental_patient_id,e.ydental_actor_id,e.ydental_station_id) IS DISTINCT FROM (x.ydental_store_id,x.ydental_patient_id,lx.ydental_actor_id,e.ydental_station_id)', 'fee_math_original': 'SELECT count(*) FROM ydental_treatment_fee f JOIN ydental_treatment_event e ON e.id=f.ydental_event_id LEFT JOIN ydental_intake_snapshot p ON p.id=f.ydental_price_snapshot_id LEFT JOIN ydental_treatment_price_review r ON r.id=f.ydental_price_review_id WHERE f.ydental_unit_price<=0 OR abs(f.ydental_amount-round((e.ydental_quantity*f.ydental_unit_price)::numeric,2))>0.000001 OR f.ydental_unit_price IS DISTINCT FROM coalesce(p.ydental_unit_price,r.ydental_unit_price)', 'clinical_inventory_source': "SELECT count(*) FROM ydental_treatment_consumption c JOIN ydental_treatment_event e ON e.id=c.ydental_event_id JOIN ydental_inventory_event i ON i.id=c.ydental_inventory_event_id WHERE i.ydental_source_namespace<>'s08b-clinical' OR i.ydental_source_key<>('consumption-'||c.id) OR i.ydental_actual_at<>e.ydental_actual_at OR i.ydental_responsible_id<>e.ydental_actor_id OR i.ydental_lot_id<>c.ydental_lot_id OR i.ydental_kind<>c.ydental_kind", 'prescription_overdispense': "SELECT count(*) FROM ydental_treatment_line l WHERE l.ydental_quantity<(SELECT coalesce(sum(e.ydental_quantity),0) FROM ydental_treatment_event e WHERE e.ydental_order_line_id=l.id AND e.ydental_kind='prescription')", 'duplicate_live_segment': "SELECT count(*) FROM (SELECT ydental_order_id FROM ydental_treatment_segment WHERE state IN ('pending','active') GROUP BY 1 HAVING count(*)>1) q", 'finished_segment_history': "SELECT count(*) FROM ydental_treatment_segment s JOIN ydental_queue_execution e ON e.id=s.ydental_execution_id JOIN ydental_intake_task t ON t.id=s.ydental_task_id WHERE s.state='done' AND (e.state<>'completed' OR e.ydental_ended_at IS NULL OR t.state<>'done' OR s.ydental_finished_at IS NULL)", 'pending_segment_not_enqueued': "SELECT count(*) FROM ydental_treatment_segment s JOIN ydental_intake_task t ON t.id=s.ydental_task_id WHERE s.state='pending' AND t.state='pending' AND EXISTS(SELECT 1 FROM ydental_queue_entry e WHERE e.ydental_task_id=t.id AND e.state IN ('waiting','calling','serving'))", 'immutable_delta_price': 'SELECT count(*) FROM ydental_treatment_event e JOIN ydental_treatment_event p ON p.id=e.ydental_parent_id WHERE (e.ydental_price_snapshot_id,e.ydental_price_review_id) IS DISTINCT FROM (p.ydental_price_snapshot_id,p.ydental_price_review_id)', 'event_audit_once': "SELECT count(*) FROM ydental_treatment_event e WHERE (SELECT count(*) FROM ydental_access_audit a WHERE a.ydental_event='treatment.actual_execution' AND a.ydental_target_model='ydental.treatment.event' AND a.ydental_target_id=e.id)<>1"})
for name,query in queries.items():env.cr.execute(query);result['invariants'][name]=env.cr.fetchone()[0]
env.cr.execute("SELECT ydental_event,count(*) FROM ydental_access_audit WHERE ydental_event LIKE 'clinical.%' OR ydental_event LIKE 'treatment.%' GROUP BY ydental_event ORDER BY ydental_event")
result['audit_events']=dict(env.cr.fetchall());result['result']='PASS' if not any(result['invariants'].values()) else 'FAIL'
root=Path(__file__).resolve().parents[1];out=root/'docs/evidence/s08b/audit-attempts';out.mkdir(parents=True,exist_ok=True)
(out/(run.name+'-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%f')+'.json')).write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'result':result['result'],'invariants':result['invariants']}))
assert result['result']=='PASS'
